def verify_password(plain_password: str, stored_password: str) -> bool:
    """Verify a plaintext password against a stored password spec."""
    if stored_password.startswith(BCRYPT_PASSWORD_PREFIX):
        hashed_password = stored_password[len(BCRYPT_PASSWORD_PREFIX) :]
        if not hashed_password:
            return False
        try:
            return bcrypt.checkpw(
                plain_password.encode("utf-8"), hashed_password.encode("utf-8")
            )
        except ValueError:
            return False

    return stored_password == plain_password

def sign(self, msg: bytes, key: OctKey) -> bytes:
    # it is faster than the one in cryptography
    op_key = key.get_op_key("sign")
    return hmac.new(op_key, msg, self.hash_alg).digest()

